# IPTVPremium: capas em duas janelas, prioridade ao abrir e foco nas categorias. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesScreen.kt'; Allowed = @('67708B989906D1D850BC5EEEF17A3F205ECBDF3BF23C4C19466FA498D6D09ECF'); MayCreate = $false; After = '1A72C1A87015082BAC2F5738AA86C9442B4EC71FB02BF20ADBEAD7ED80DC1FC3'; PayloadHash = '1A72C1A87015082BAC2F5738AA86C9442B4EC71FB02BF20ADBEAD7ED80DC1FC3'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Allowed = @('48DAA0B2C092DC727ADAB7170BF949A8FABED3710A01A86A8C1EDE38C6155779'); MayCreate = $false; After = 'A4A460247149534DD4F06815C6986B18B93C8631491B36624ED8455016B10BE4'; PayloadHash = 'A4A460247149534DD4F06815C6986B18B93C8631491B36624ED8455016B10BE4'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogPosterLoading.kt'; Allowed = @(); MayCreate = $true; After = 'A00DD9DF373FF1D48DFA13154BCD88D7CF1DC7F18E95F6D7C169375A67567D43'; PayloadHash = 'A00DD9DF373FF1D48DFA13154BCD88D7CF1DC7F18E95F6D7C169375A67567D43'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogFavoriteHeart.kt'; Allowed = @(); MayCreate = $true; After = '4F7741092C4C0F70308492D1F84A497BA1F5B5E262FDF4902123F895328605F4'; PayloadHash = '4F7741092C4C0F70308492D1F84A497BA1F5B5E262FDF4902123F895328605F4'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/AppNavigation.kt'; Allowed = @('8C9AF04CDE81C16955A896C5E104E2770F1E2CD1CEF2AA7AD23A764ACA9C1C25'); MayCreate = $false; After = '0D6BF6D466D147E0BF876308ED15436FB1FFB7CDEBC5671B4341D2627D5403E0'; PayloadHash = '0D6BF6D466D147E0BF876308ED15436FB1FFB7CDEBC5671B4341D2627D5403E0'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/CatalogPosterRequests.kt'; Allowed = @(); MayCreate = $true; After = 'DCCCA5526B179548B80C53127E5C51388390B4F8840D3029024026D3A6D1F463'; PayloadHash = 'DCCCA5526B179548B80C53127E5C51388390B4F8840D3029024026D3A6D1F463'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterBatchPolicy.kt'; Allowed = @('390D9614D71818EB2B26DA3F4FE5061EA3927C71AA23D51046CCD81750166E44'); MayCreate = $false; After = 'D43033B394ACCB3021A744F021840E40140F92E96A9CF3CB7416F9E9D6BCA6AA'; PayloadHash = 'D43033B394ACCB3021A744F021840E40140F92E96A9CF3CB7416F9E9D6BCA6AA'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/repository/CatalogEntryRulesDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = '57D260E88F6C249E9DAD14D0BEE22D9F9178C51E6DCE2F7F500B1103E1418803'; PayloadHash = '57D260E88F6C249E9DAD14D0BEE22D9F9178C51E6DCE2F7F500B1103E1418803'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/cache/CatalogPosterRulesDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = '7FDD51A95E331E8B3F554E89B925D9B57EA065EA0DE88D70C2234A32968DBD73'; PayloadHash = '7FDD51A95E331E8B3F554E89B925D9B57EA065EA0DE88D70C2234A32968DBD73'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = Get-TextHash $original
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/capas-janela-prioridade-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: proxima janela de capas, cancelamento no clique, foco nas categorias e coracao junto da nota.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
